function original(d, n) {
  var p = {}; Object.keys(d.common).forEach(function(k) {p[k] = d.common[k];});
  Object.keys(d.rows[n]).forEach(function(k) {p[k] = d.rows[n][k];}); return p;
}
function currentOriginal() {return original(active, index);}
function entry() {return states[active.key][currentOriginal().sample_id] || {};}
function legendLabel(code) {
  var match = LEGENDS[active.site].filter(function(c) {return c.code === Number(code);})[0];
  return match ? match.code + ' — ' + match.name : '';
}
function classCode(value) {return value ? Number(value.split(' — ')[0]) : '';}
function same(a,b) {return JSON.stringify(a) === JSON.stringify(b);}
function allowedCodes(d) {return LEGENDS[d.site].map(function(c) {return c.code;});}
function reviewValid(d, e) {
  if (!e.reviewer || !e.reviewer.trim()) return 'Enter reviewer name or initials.';
  if (['accept','reject','unresolved'].indexOf(e.decision) < 0) return 'Choose accept, reject or unresolved.';
  if (e.decision === 'accept') {
    if (allowedCodes(d).indexOf(e.reviewed_class) < 0) return 'Choose a reviewed class before accepting.';
    if (['high','medium','low'].indexOf(e.confidence) < 0) return 'Choose confidence before accepting.';
    if (!e.imagery_source || !e.imagery_id || !e.imagery_dates) return 'Record dated evidence using the scene button or evidence fields.';
  } else if (!e.notes || !e.notes.trim()) return 'Explain rejection or uncertainty in Notes.';
  return '';
}
