function label(text,style) {return ui.Label(text,style || small);}
function heading(text) {panel.add(label(text,{fontSize:'16px',fontWeight:'bold',margin:'10px 0 4px 0'}));}
panel.add(label('SES410 • Human reference review',{fontSize:'20px',fontWeight:'bold',color:'#173d35'}));
panel.add(label('Internal 2021 review. Entries stay in this tab until you download them. Download checkpoints often and before closing/reloading.',{fontSize:'13px',color:'#9a3412',whiteSpace:'pre-wrap'}));
heading('1. Choose your assigned dataset');
var datasetSelect = ui.Select({items:datasetLabels,placeholder:'Choose dataset',style:{stretch:'horizontal'}});
panel.add(datasetSelect);
var blindBanner=label('',{fontWeight:'bold',fontSize:'13px',color:'#854d0e',whiteSpace:'pre-wrap'}); panel.add(blindBanner);
var identity=label('',{fontSize:'12px',whiteSpace:'pre-wrap'}); panel.add(identity);
var progress=label('',{fontWeight:'bold',fontSize:'13px'}); panel.add(progress);
var proposal=label('',{fontWeight:'bold',color:'#14532d',whiteSpace:'pre-wrap'}); panel.add(proposal);
var previous=ui.Button({label:'Previous',onClick:function(){navigate(-1);}});
var next=ui.Button({label:'Next',onClick:function(){navigate(1);}});
var jump=ui.Textbox({placeholder:'Point number',style:{width:'95px'}});
var go=ui.Button('Go',function(){stash();var n=Number(jump.getValue());if(n>=1&&n<=active.rows.length&&n===Math.floor(n)){index=n-1;showPoint();}else status.setValue('Enter a whole point number within this dataset.');});
panel.add(ui.Panel([previous,next,jump,go],ui.Panel.Layout.flow('horizontal')));
heading('2. Inspect dated 2021 imagery');
var imageryStatus=label('Loading 2021 scenes…');panel.add(imageryStatus);
var sceneSelect=ui.Select({items:[],placeholder:'Clear 2021 scene',style:{stretch:'horizontal'}});panel.add(sceneSelect);
var colour=ui.Select({items:['Natural colour','Vegetation false colour'],value:'Natural colour',style:{stretch:'horizontal'}});panel.add(colour);
panel.add(label('10 m Sentinel-2 scenes; cloud-masked, not ground truth. Check several dates. Finer dated imagery or field records may be needed. Mark unresolved if evidence is insufficient.'));
var useScene=ui.Button({label:'Use displayed dated scene as evidence',onClick:function(){
  if(!selectedScene){status.setValue('Wait for a dated scene, or enter independent evidence below.');return;}
  var ids=evidenceId.getValue()||'', dates=evidenceDates.getValue()||'';
  evidenceSource.setValue('Copernicus Sentinel-2 SR (human interpretation)',false);
  if(ids.indexOf(selectedScene.id)<0)evidenceId.setValue(ids ? ids+'; '+selectedScene.id : selectedScene.id,false);
  if(dates.indexOf(selectedScene.date)<0)evidenceDates.setValue(dates ? dates+'; '+selectedScene.date : selectedScene.date,false);
  stash(); status.setValue('Evidence recorded. Interpret the imagery; no class has been assigned.');
}});panel.add(useScene);
heading('3. Use the agreed site legend');
var legendPanel=ui.Panel();panel.add(legendPanel);
panel.add(label('Mixed, changing or out-of-legend cover: explain in Notes and mark unresolved. Do not force it into a class.'));
heading('4. Record your interpretation');
var reviewer=ui.Textbox({placeholder:'Reviewer name or initials',style:{stretch:'horizontal'}});
var reviewedClass=ui.Select({items:[],placeholder:'Reviewed class — choose from evidence',style:{stretch:'horizontal'}});
var confidence=ui.Select({items:['high','medium','low'],placeholder:'Confidence',style:{stretch:'horizontal'}});
var decision=ui.Select({items:['accept','reject','unresolved'],placeholder:'Decision',style:{stretch:'horizontal'}});
var notes=ui.Textbox({placeholder:'Notes: observed cover, uncertainty or rejection reason',style:{stretch:'horizontal'}});
var evidenceSource=ui.Textbox({placeholder:'Imagery / field source used',style:{stretch:'horizontal'}});
var evidenceId=ui.Textbox({placeholder:'Exact scene, archive or field-record identifier(s)',style:{stretch:'horizontal'}});
var evidenceDates=ui.Textbox({placeholder:'Evidence acquisition date(s), e.g. 2021-07-18',style:{stretch:'horizontal'}});
[
 ['Reviewer',reviewer],['Reviewed class',reviewedClass],['Confidence',confidence],['Decision',decision],
 ['Notes',notes],['Evidence source',evidenceSource],['Evidence identifier(s)',evidenceId],['Evidence date(s)',evidenceDates]
].forEach(function(pair){panel.add(label(pair[0],{fontWeight:'bold',fontSize:'12px',margin:'6px 0 0 0'}));panel.add(pair[1]);});
var status=label('',{fontSize:'13px',color:'#9a3412',whiteSpace:'pre-wrap'});panel.add(status);
function commitEntry(){
  stash();var e=entry(),problem=reviewValid(active,e);if(problem){status.setValue(problem);return;}
  e.review_status='completed';e.date_reviewed=new Date().toISOString().slice(0,10);
  states[active.key][currentOriginal().sample_id]=e;updateProgress();
  status.setValue('Entry saved in this tab. Download a checkpoint to preserve it after closing.');
}
panel.add(ui.Button({label:'Save this entry in the session',onClick:commitEntry}));
heading('5. Download this dataset only');
panel.add(label('Downloads include all original points, with pending/draft/completed status. Training and validation are never combined. Downloaded reviews still require coordinator approval before asset upload.'));
var downloads=ui.Panel();
var exportButton=ui.Button({label:'Prepare CSV + resumable GeoJSON checkpoint',onClick:prepareDownloads});panel.add(exportButton);panel.add(downloads);
heading('Resume a saved GeoJSON checkpoint');
panel.add(label('Select the matching dataset above. Open your downloaded GeoJSON file in a text editor, copy all its contents, paste below, then Restore. No code edits are needed. CSV is for review/upload; GeoJSON is for resuming.'));
var resume=ui.Textbox({placeholder:'Paste the complete saved GeoJSON checkpoint here',style:{stretch:'horizontal'}});panel.add(resume);
panel.add(ui.Button({label:'Restore checkpoint for selected dataset',onClick:restoreCheckpoint}));
panel.add(label('Keyboard alternative: use this action menu if you prefer keyboard navigation. The same save/download checks apply.'));
var actionMenu=ui.Select({items:['Previous point','Next point','Save this entry','Prepare downloads','Restore checkpoint'],placeholder:'Review actions (keyboard alternative)',style:{stretch:'horizontal'}});
actionMenu.onChange(function(value){if(!value)return;actionMenu.setValue(null,false);if(value==='Previous point')navigate(-1);else if(value==='Next point')navigate(1);else if(value==='Save this entry')commitEntry();else if(value==='Prepare downloads')prepareDownloads();else if(value==='Restore checkpoint')restoreCheckpoint();});panel.add(actionMenu);
ui.root.clear();ui.root.add(ui.SplitPanel({firstPanel:panel,secondPanel:map,orientation:'horizontal',wipe:false,style:{stretch:'both'}}));
function readForm(){return {reviewed_class:classCode(reviewedClass.getValue()),confidence:confidence.getValue()||'',decision:decision.getValue()||'pending',notes:notes.getValue()||'',reviewer:reviewer.getValue()||'',imagery_source:evidenceSource.getValue()||'',imagery_id:evidenceId.getValue()||'',imagery_dates:evidenceDates.getValue()||''};}
function stash(){
  if(loadingForm||!active)return;
  var id=currentOriginal().sample_id,old=entry(),fresh=readForm();
  var comparable={};Object.keys(fresh).forEach(function(k){comparable[k]=old[k]===undefined?(k==='decision'?'pending':''):old[k];});
  if(!same(fresh,comparable)){
    fresh.date_reviewed=old.date_reviewed||'';fresh.review_status='draft';
    states[active.key][id]=fresh;downloads.clear();updateProgress();
    status.setValue('Draft kept in this tab. Save entry when ready; download before closing.');
  }
}
[reviewer,reviewedClass,confidence,decision,notes,evidenceSource,evidenceId,evidenceDates].forEach(function(w){w.onChange(stash);});
function updateProgress(){
  var complete=Object.keys(states[active.key]).filter(function(id){return states[active.key][id].review_status==='completed';}).length;
  progress.setValue('Point '+(index+1)+' / '+active.rows.length+'  •  '+complete+' completed');
  previous.setDisabled(index===0);next.setDisabled(index===active.rows.length-1);
}
function navigate(step){stash();index=Math.max(0,Math.min(active.rows.length-1,index+step));showPoint();}
function showPoint(){
  token++;positions[active.key]=index;var p=currentOriginal(),e=entry();loadingForm=true;
  identity.setValue(p.sample_id+'\n'+p.site_name+' • '+Number(p.longitude).toFixed(6)+', '+Number(p.latitude).toFixed(6)+' • 2021');
  blindBanner.setValue(active.training?'TRAINING: proposal is visible; verify it against evidence.':'BLIND VALIDATION: no proposals, product labels, predictions or embeddings. Do not open training or prediction maps.');
  proposal.style().set('shown',active.training);
  proposal.setValue(active.training?'Proposed class: '+legendLabel(p.candidate_class):'');
  legendPanel.clear();LEGENDS[active.site].forEach(function(c){legendPanel.add(label(c.code+' — '+c.name+': '+c.definition));});
  reviewedClass.items().reset(LEGENDS[active.site].map(function(c){return c.code+' — '+c.name;}));
  reviewedClass.setValue(e.reviewed_class!==undefined&&e.reviewed_class!==''?legendLabel(e.reviewed_class):null,false);
  confidence.setValue(e.confidence||null,false);decision.setValue(e.decision&&e.decision!=='pending'?e.decision:null,false);
  reviewer.setValue(e.reviewer||'',false);notes.setValue(e.notes||'',false);
  evidenceSource.setValue(e.imagery_source||'',false);evidenceId.setValue(e.imagery_id||'',false);evidenceDates.setValue(e.imagery_dates||'',false);
  jump.setValue(String(index+1),false);loadingForm=false;downloads.clear();updateProgress();
  status.setValue(e.review_status==='completed'?'Completed entry restored from this session.':'No automatic label. Navigation retains drafts in this tab.');
  map.layers().reset();var pt=ee.Geometry.Point([p.longitude,p.latitude]);
  map.setCenter(p.longitude,p.latitude,16);
  map.addLayer(ee.FeatureCollection([ee.Feature(pt)]).style({color:'ff2222',pointSize:5,width:2}),{},'Review point');
  selectedScene=null;sceneRows=[];sceneSelect.items().reset([]);sceneSelect.setDisabled(true);useScene.setDisabled(true);
  imageryStatus.setValue('Finding clear 2021 scenes at this point…');
  var myToken=token,cacheKey=p.sample_id;
  if(sceneCache[cacheKey]){receiveScenes(sceneCache[cacheKey],myToken);return;}
  var scenes=ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED').filterBounds(pt)
    .filterDate('2021-01-01','2022-01-01').sort('CLOUDY_PIXEL_PERCENTAGE').limit(30)
    .map(function(im){var scl=im.select('SCL');var clear=scl.neq(0).and(scl.neq(1)).and(scl.neq(3)).and(scl.lt(7));
      var value=im.select('B4').updateMask(clear).reduceRegion({reducer:ee.Reducer.first(),geometry:pt,scale:10,maxPixels:100}).get('B4');
      return im.set('_clear_at_point',ee.Algorithms.If(ee.Algorithms.IsEqual(value,null),0,1));})
    .filter(ee.Filter.eq('_clear_at_point',1));
  scenes.toList(30).map(function(x){var im=ee.Image(x);return ee.Dictionary({id:ee.String('COPERNICUS/S2_SR_HARMONIZED/').cat(ee.String(im.get('system:index'))),date:im.date().format('YYYY-MM-dd'),tile:im.get('MGRS_TILE'),cloud:im.get('CLOUDY_PIXEL_PERCENTAGE')});})
    .evaluate(function(rows,error){if(myToken!==token)return;if(error){imageryStatus.setValue('Imagery query failed. Retry the point, or use documented independent evidence.');return;}sceneCache[cacheKey]=rows;receiveScenes(rows,myToken);});
}
function receiveScenes(rows,myToken){
  if(myToken!==token)return;sceneRows=rows;
  if(!rows.length){imageryStatus.setValue('No clear 2021 scene found among 30 least-cloudy candidates. Use independently dated evidence or mark unresolved.');return;}
  sceneSelect.items().reset(rows.map(function(r){return r.date+' • tile '+r.tile+' • '+r.id.split('/').pop().split('_')[0];}));sceneSelect.setDisabled(false);useScene.setDisabled(false);
  sceneSelect.setValue(rows[0].date+' • tile '+rows[0].tile+' • '+rows[0].id.split('/').pop().split('_')[0],false);displayScene(rows[0]);
}
function displayScene(row){
  selectedScene=row;imageryStatus.setValue('Acquired '+row.date+' • Sentinel-2 SR • 10 m pixels. Scene '+row.id);
  var im=ee.Image(row.id),scl=im.select('SCL');var clear=scl.neq(0).and(scl.neq(1)).and(scl.neq(3)).and(scl.lt(7));
  var vis={bands:colour.getValue()==='Natural colour'?['B4','B3','B2']:['B8','B4','B3'],min:0,max:3000,gamma:1.2};
  imageLayer=ui.Map.Layer(im.updateMask(clear),vis,'Dated imagery '+row.date);map.layers().set(0,imageLayer);
  var p=currentOriginal();map.layers().set(1,ui.Map.Layer(ee.FeatureCollection([ee.Feature(ee.Geometry.Point([p.longitude,p.latitude]))]).style({color:'ff2222',pointSize:5,width:2}),{},'Review point'));
}
sceneSelect.onChange(function(value){var r=sceneRows.filter(function(s){return s.date+' • tile '+s.tile+' • '+s.id.split('/').pop().split('_')[0]===value;})[0];if(r)displayScene(r);});
colour.onChange(function(){if(selectedScene)displayScene(selectedScene);});
datasetSelect.onChange(function(value){stash();active=DATASETS.filter(function(d){return d.label===value;})[0];states[active.key]=states[active.key]||{};index=positions[active.key]||0;showPoint();});
function outputProperties(d,n){
  var p=original(d,n),e=states[d.key][p.sample_id]||{};
  Object.keys(e).forEach(function(k){p[k]=e[k];});
  p.review_dataset=d.key;p.review_app_version='SES410_REVIEW_APP_V1';p.review_status=e.review_status||'pending';
  p.reviewed=e.review_status==='completed'?1:0;
  // Original role and label_source remain intact. This is a review archive, not an approved classifier input.
  return p;
}
function prepareDownloads(){
  stash();downloads.clear();exportButton.setDisabled(true);var d=active;
  var features=d.rows.map(function(r,n){var p=outputProperties(d,n);return ee.Feature(ee.Geometry.Point([p.longitude,p.latitude]),p);});
  var fc=ee.FeatureCollection(features),pending=2,exportToken=token;
  status.setValue('Preparing this dataset only. Entries remain in this tab until you click and save both downloads.');
  ['csv','geojson'].forEach(function(format){fc.getDownloadURL(format,null,d.key+'_reviewed',function(url,error){
    pending--;if(pending===0)exportButton.setDisabled(false);
    if(exportToken!==token)return;
    if(error||!url){status.setValue('Download preparation failed; entries remain in this tab. Try again.');return;}
    downloads.add(ui.Label({value:format==='csv'?'Download CSV review table':'Download GeoJSON checkpoint (for resuming)',targetUrl:url,style:{color:'#075985',fontWeight:'bold'}}));
    if(pending===0)status.setValue('Click BOTH download links and save the files. Keep each dataset separate. Download links are temporary.');
  });});
}
function restoreCheckpoint(){
  stash();var doc;try{doc=JSON.parse(resume.getValue());}catch(err){status.setValue('Paste the whole downloaded GeoJSON file, including its opening and closing braces.');return;}
  if(!doc||doc.type!=='FeatureCollection'||!Array.isArray(doc.features)){status.setValue('This is not a GeoJSON review checkpoint.');return;}
  var expected={},seen={},imported={},d=active;
  d.rows.forEach(function(r,n){var p=original(d,n);expected[p.sample_id]=p;});
  var failure='';doc.features.forEach(function(f){
    var p=f.properties||{},o=expected[p.sample_id],g=f.geometry||{};
    if(!o||seen[p.sample_id]||p.review_dataset!==d.key||!g.coordinates||g.type!=='Point'||
       Math.abs(g.coordinates[0]-o.longitude)>1e-9||Math.abs(g.coordinates[1]-o.latitude)>1e-9||
       p.role!==o.role||p.site!==o.site||Number(p.target_year)!==2021){failure='Checkpoint IDs, dataset or original geometry/metadata do not match.';return;}
    seen[p.sample_id]=true;var e={};
    ['reviewed_class','confidence','decision','notes','reviewer','imagery_source','imagery_id','imagery_dates','date_reviewed','review_status'].forEach(function(k){if(p[k]!==undefined&&p[k]!==null)e[k]=p[k];});
    if(e.reviewed_class!==undefined&&e.reviewed_class!=='')e.reviewed_class=Number(e.reviewed_class);
    if(e.review_status==='completed'&&reviewValid(d,e))failure='A completed entry is missing required evidence or review fields.';
    var existing=states[d.key][p.sample_id];
    if(existing&&existing.review_status!=='pending'&&!same(existing,e)){failure='Conflicting entries already exist in this session. Open a fresh app tab to restore this checkpoint without overwriting them.';return;}
    imported[p.sample_id]=e;
  });
  if(doc.features.length!==d.rows.length||Object.keys(seen).length!==d.rows.length)failure='Checkpoint must contain the full selected dataset.';
  if(failure){status.setValue(failure+' Nothing was replaced.');return;}
  states[d.key]=imported;resume.setValue('',false);showPoint();status.setValue('Checkpoint restored for this dataset. Original IDs and coordinates checked.');
}
datasetSelect.setValue(datasetLabels[0],true);





